# Extensions rencontrées dans les dossiers techniques existants (1 023 fichiers en production, 2026-10-25) :
# xlsm 94, pub 21, bmp 4, vsdx 1 étaient refusées par la liste initiale.
EXTENSIONS_DOSSIER_TECHNIQUE_EN_PLUS = ['xlsm', 'xlsb', 'pub', 'bmp', 'vsdx', 'gif', 'tif', 'tiff']


def rattraper_versions_existantes(apps, schema_editor):
    """Chaque fichier déjà déposé reçoit sa version 1 (son contenu actuel)."""
    Fichier = apps.get_model('sync', 'Fichier')
    FichierVersion = apps.get_model('sync', 'FichierVersion')
    deja = set(FichierVersion.objects.values_list('fichier_id', flat=True))
    FichierVersion.objects.bulk_create([
        FichierVersion(
            fichier_id=f.id, numero=1, nom=f.nom, storage_path=f.storage_path, sha256=f.sha256,
            taille=f.taille, origine='depot', depose_par_id=f.depose_par_id,
        )
        for f in Fichier.objects.exclude(id__in=deja)
    ])


def elargir_extensions(apps, schema_editor):
    Categorie = apps.get_model('sync', 'CategorieFichier')
    categorie = Categorie.objects.filter(code='dossier_technique').first()
    if categorie:
        categorie.extensions = sorted(set(categorie.extensions) | set(EXTENSIONS_DOSSIER_TECHNIQUE_EN_PLUS))
        categorie.save(update_fields=['extensions'])


def retirer_extensions(apps, schema_editor):
    Categorie = apps.get_model('sync', 'CategorieFichier')
    categorie = Categorie.objects.filter(code='dossier_technique').first()
    if categorie:
        categorie.extensions = [e for e in categorie.extensions if e not in EXTENSIONS_DOSSIER_TECHNIQUE_EN_PLUS]
        categorie.save(update_fields=['extensions'])


